{"output":"package hub

import (
    "context"
    "fmt"
    "log"
    "net/http"
    "sync"
    "time"

    "github.com/gorilla/websocket"
)

type Role string

const (
    RoleNewCLI Role = "newcli"
    RoleCodex  Role = "codex"
)

type peer struct {
    conn   *websocket.Conn
    role   Role
    token  string
    closed chan struct{}
}

type pair struct {
    token string
    a     *peer // newcli
    b     *peer // codex
}

type Hub struct {
    mu    sync.Mutex
    pairs map[string]*pair

    allowedTokens map[string]struct{}
    logLimit      int
}

func New(allowed []string, logLimit int) *Hub {
    at := map[string]struct{}{}
    if len(allowed) > 0 {
        for _, t := range allowed {
            at[t] = struct{}{}
        }
    }
    return &Hub{
        pairs:         make(map[string]*pair),
        allowedTokens: at,
        logLimit:      logLimit,
    }
}

var upgrader = websocket.Upgrader{
    ReadBufferSize:  64 << 10,
    WriteBufferSize: 64 << 10,
    CheckOrigin: func(r *http.Request) bool {
        // Allow all origins for demo; put your own policy here.
        return true
    },
}

func (h *Hub) ServeWS(w http.ResponseWriter, r *http.Request) {
    q := r.URL.Query()
    roleStr := q.Get("role")
    token := q.Get("token")
    if roleStr == "" || token == "" {
        http.Error(w, "missing role or token", http.StatusBadRequest)
        return
    }
    if len(h.allowedTokens) > 0 {
        if _, ok := h.allowedTokens[token]; !ok {
            http.Error(w, "token not allowed", http.StatusForbidden)
            return
        }
    }

    var role Role
    switch roleStr {
    case string(RoleNewCLI):
        role = RoleNewCLI
    case string(RoleCodex):
        role = RoleCodex
    default:
        http.Error(w, "invalid role", http.StatusBadRequest)
        return
    }

    c, err := upgrader.Upgrade(w, r, nil)
    if err != nil {
        log.Printf("upgrade failed: %v", err)
        return
    }

    p := &peer{conn: c, role: role, token: token, closed: make(chan struct{})}
    pr := h.addPeer(p)

    log.Printf("connected: role=%s token=%s remote=%s", role, token, r.RemoteAddr)

    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()

    // reader goroutine
    go func() {
        defer close(p.closed)
        for {
            mt, msg, err := c.ReadMessage()
            if err != nil {
                // log and break
                log.Printf("read err role=%s token=%s: %v", role, token, err)
                return
            }
            h.logMsg(role, token, "in", mt, msg)
            h.forward(pr, p, mt, msg)
        }
    }()

    // Wait until peer is closed
    select {
    case <-p.closed:
        // continue to cleanup
    case <-ctx.Done():
    }

    h.removePeer(p)
    _ = c.Close()
    log.Printf("disconnected: role=%s token=%s", role, token)
}

func (h *Hub) logMsg(role Role, token, dir string, mt int, msg []byte) {
    typ := "text"
    if mt == websocket.BinaryMessage {
        typ = "bin"
    }
    preview := msg
    if h.logLimit > 0 && len(preview) > h.logLimit {
        preview = preview[:h.logLimit]
    }
    // Truncate preview at printable boundary for text.
    // For simplicity we print as %q (Go escapes non-printables).
    log.Printf("msg %s role=%s token=%s type=%s len=%d preview=%q", dir, role, token, typ, len(msg), preview)
}

func (h *Hub) addPeer(p *peer) *pair {
    h.mu.Lock()
    defer h.mu.Unlock()
    pr, ok := h.pairs[p.token]
    if !ok {
        pr = &pair{token: p.token}
        h.pairs[p.token] = pr
    }
    if p.role == RoleNewCLI {
        if pr.a != nil {
            // Close existing
            _ = pr.a.conn.WriteControl(websocket.CloseMessage, websocket.FormatCloseMessage(websocket.CloseNormalClosure, "replaced"), time.Now().Add(2*time.Second))
            _ = pr.a.conn.Close()
        }
        pr.a = p
    } else {
        if pr.b != nil {
            _ = pr.b.conn.WriteControl(websocket.CloseMessage, websocket.FormatCloseMessage(websocket.CloseNormalClosure, "replaced"), time.Now().Add(2*time.Second))
            _ = pr.b.conn.Close()
        }
        pr.b = p
    }
    return pr
}

func (h *Hub) removePeer(p *peer) {
    h.mu.Lock()
    defer h.mu.Unlock()
    pr, ok := h.pairs[p.token]
    if !ok {
        return
    }
    if pr.a == p {
        pr.a = nil
    }
    if pr.b == p {
        pr.b = nil
    }
    if pr.a == nil && pr.b == nil {
        delete(h.pairs, p.token)
    }
}

func (h *Hub) forward(pr *pair, src *peer, mt int, msg []byte) {
    dst := h.otherLocked(pr, src)
    if dst == nil {
        // no peer to forward; drop
        return
    }
    // Forward write with deadline
    dst.conn.SetWriteDeadline(time.Now().Add(30 * time.Second))
    if err := dst.conn.WriteMessage(mt, msg); err != nil {
        log.Printf("forward err token=%s from=%s to=%s: %v", src.token, src.role, dst.role, err)
        _ = dst.conn.Close()
    } else {
        h.logMsg(src.role, src.token, fmt.Sprintf("out->%s", dst.role), mt, msg)
    }
}

func (h *Hub) otherLocked(pr *pair, src *peer) *peer {
    h.mu.Lock()
    defer h.mu.Unlock()
    if src.role == RoleNewCLI {
        return pr.b
    }
    return pr.a
}


