func main() {
    var (
        addrFlag   string
        configPath string
    )

    flag.StringVar(&addrFlag, "addr", "", "listen address, e.g. :8080")
    flag.StringVar(&configPath, "config", "", "config JSON path (default: %USERPROFILE%/.codex/relay.json)")
    flag.Parse()

    cfg, err := config.Load(configPath)
    if err != nil {
        log.Fatalf("load config: %v", err)
    }
    if addrFlag != "" {
        cfg.ListenAddr = addrFlag
    }

    // Optional file logging
    if cfg.LogDir != "" {
        if err := os.MkdirAll(cfg.LogDir, 0o755); err != nil {
            log.Fatalf("create log dir: %v", err)
        }
        logPath := filepath.Join(cfg.LogDir, "relay.log")
        f, err := os.OpenFile(logPath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
        if err != nil {
            log.Fatalf("open log file: %v", err)
        }
        log.SetOutput(io.MultiWriter(os.Stdout, f))
        log.Printf("file logging to %s", logPath)
    }

    h := hub.New(cfg.AllowedTokens, cfg.MaxMessageLogBytes)

    mux := http.NewServeMux()
    mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
        w.WriteHeader(http.StatusOK)
        _, _ = w.Write([]byte("ok"))
    })
    mux.HandleFunc("/ws", h.ServeWS)

    log.Printf("starting relay on %s", cfg.ListenAddr)
    log.Printf("allowed tokens: %s", summarizeTokens(cfg.AllowedTokens))
    if err := http.ListenAndServe(cfg.ListenAddr, logRequest(mux)); err != nil {
        log.Fatalf("server error: %v", err)
    }
}

func summarizeTokens(ts []string) string {
    if len(ts) == 0 {
        return "<any>"
    }
    if len(ts) <= 5 {
        return fmt.Sprintf("%v", ts)
    }
    return fmt.Sprintf("%v (+%d more)", ts[:5], len(ts)-5)
}

func logRequest(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        log.Printf("%s %s from %s", r.Method, r.URL.String(), r.RemoteAddr)
        next.ServeHTTP(w, r)
    })
}

