    )

    flag.StringVar(&addrFlag, "addr", "", "listen address, e.g. :8080")
    flag.StringVar(&configPath, "config", "", "config JSON file or directory (default: %USERPROFILE%/.codex/relay.json)")
    flag.BoolVar(&testFlag, "console-test", false, "console test mode: bridge stdin/stdout via local hub")
    flag.Parse()

    // Default to repo config folder if none provided
    if configPath == "" {
        configPath = filepath.Join(".", "internal", "config", ".codex")
    }

    cfg, err := config.Load(configPath)
    if err != nil {
        log.Fatalf("load config: %v", err)
    }
    if addrFlag != "" {
        cfg.ListenAddr = addrFlag
    }
    if testFlag {
        cfg.ConsoleTest = true
    }

    // Optional file logging
    if cfg.LogDir != "" {
        if err := os.MkdirAll(cfg.LogDir, 0o755); err != nil {
            log.Fatalf("create log dir: %v", err)
        }
        logPath := filepath.Join(cfg.LogDir, "relay.log")
        f, err := os.OpenFile(logPath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
        if err != nil {
            log.Fatalf("open log file: %v", err)
        }
        log.SetOutput(io.MultiWriter(os.Stdout, f))
        log.Printf("file logging to %s", logPath)
    }

    mux := http.NewServeMux()
    mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
        w.WriteHeader(http.StatusOK)
        _, _ = w.Write([]byte("ok"))
    })
    mux.HandleFunc("/ws", makeBridgeHandler(cfg))

    // Start HTTP server
    srv := &http.Server{Addr: cfg.ListenAddr, Handler: logRequest(mux)}
    go func() {
        log.Printf("starting relay on %s", cfg.ListenAddr)
        log.Printf("allowed tokens: %s", summarizeTokens(cfg.AllowedTokens))
        if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
