// --- Bridge handler: accepts downstream WS, validates relay token, dials upstream, and pipes frames.

var wsUpgrader = websocket.Upgrader{
    ReadBufferSize:  64 << 10,
    WriteBufferSize: 64 << 10,
    CheckOrigin: func(r *http.Request) bool { return true },
}

func makeBridgeHandler(cfg config.Config) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        // Enforce relay token if configured
        gate := r.URL.Query().Get("relay")
        if gate == "" {
            gate = r.Header.Get("X-Relay-Token")
        }
        if gate == "" {
            if auth := r.Header.Get("Authorization"); strings.HasPrefix(auth, "Bearer ") {
                gate = strings.TrimPrefix(auth, "Bearer ")
            }
        }
        if len(cfg.AllowedTokens) > 0 {
            allowed := false
            for _, t := range cfg.AllowedTokens {
                if gate == t {
                    allowed = true
                    break
                }
            }
            if !allowed {
                http.Error(w, "forbidden: invalid relay token", http.StatusForbidden)
                return
            }
        }

        // Upstream URL required
        if cfg.UpstreamURL == "" {
            http.Error(w, "upstream not configured", http.StatusBadGateway)
            return
        }

        // Compose upstream URL: copy all query params except relay; force role/token as provided by downstream
        uUp, err := parseWSURL(cfg.UpstreamURL)
        if err != nil {
            http.Error(w, "invalid upstream URL", http.StatusBadGateway)
            return
        }
        uq := uUp.Query()
        dq := r.URL.Query()
        for k, vs := range dq {
            if k == "relay" {
                continue
            }
            for _, v := range vs {
                uq.Add(k, v)
            }
        }
        // Ensure role default if absent
        if dq.Get("role") == "" && cfg.UpstreamRole != "" {
            uq.Set("role", cfg.UpstreamRole)
        }
        uUp.RawQuery = uq.Encode()

        // Dial upstream before upgrading client, so we can return 502 on failure
        upConn, _, err := websocket.DefaultDialer.Dial(uUp.String(), nil)
        if err != nil {
            http.Error(w, "upstream dial failed", http.StatusBadGateway)
            return
        }

        // Upgrade downstream
        downConn, err := wsUpgrader.Upgrade(w, r, nil)
        if err != nil {
            _ = upConn.Close()
            log.Printf("downstream upgrade failed: %v", err)
            return
        }

