func pump(src, dst *websocket.Conn, logLimit int, dir, gate string) {
    defer func() {
        _ = src.Close()
        _ = dst.Close()
    }()
    for {
        mt, msg, err := src.ReadMessage()
        if err != nil {
            log.Printf("pump %s read: %v", dir, err)
            return
