        if mt == websocket.BinaryMessage { typ = "bin" }
        preview := msg
        if logLimit > 0 && len(preview) > logLimit { preview = preview[:logLimit] }
        log.Printf("msg %s gate=%s type=%s len=%d preview=%q", dir, gate, typ, len(msg), preview)
        if err := dst.WriteMessage(mt, msg); err != nil {
            log.Printf("pump %s write: %v", dir, err)
            return
        }
    }
}

func parseWSURL(raw string) (*url.URL, error) {
    u, err := url.Parse(raw)
    if err != nil { return nil, err }
    switch u.Scheme {
    case "ws", "wss":
        return u, nil
    case "http":
        u.Scheme = "ws"
        return u, nil
    case "https":
        u.Scheme = "wss"
        return u, nil
    default:
        return nil, fmt.Errorf("unsupported scheme: %s", u.Scheme)
    }
}

